using System;using System.Collections;using System.Collections.Generic;using UnityEngine;
namespace Ashfall.Integration.Playable.HandsWeapons {
 public sealed class R24M60View:MonoBehaviour {
  R23Visuals visuals;Transform art,cover,box,belt,handle,offered,held,arrow;readonly List<Renderer> boxes=new List<Renderer>();bool initialized;
  public bool Ready{get;private set;}public string Failure{get;private set;}public Transform Model{get;private set;}public Transform Muzzle{get;private set;}public Transform Flash{get;private set;}
  public void InitializeModel(Transform sourceModel){if(initialized||sourceModel==null)throw new ArgumentException("M60 actual source model required");initialized=true;Model=sourceModel;StartCoroutine(Guard(Load()));}
  IEnumerator Guard(IEnumerator work){var jobs=new Stack<IEnumerator>();jobs.Push(work);while(jobs.Count>0){object value;try{var top=jobs.Peek();if(!top.MoveNext()){jobs.Pop();continue;}value=top.Current;}catch(Exception e){Failure=e.ToString();yield break;}var nested=value as IEnumerator;if(nested!=null)jobs.Push(nested);else yield return value;}Ready=true;}
  IEnumerator Load(){visuals=new R23Visuals();art=Node("Source complete main M60 body",Model);cover=Node("Source hinged M60 cover",Model);cover.localPosition=V(R24M60Definition.CoverHome);handle=Node("Source M60 actual charging knob",Model);handle.localPosition=V(R24M60Definition.HandleHome);box=Node("Source donor detachable M60 box",Model);belt=Node("Source donor eight linked M60 cartridges",Model);offered=Node("Source M60 offered donor box",Model);held=Node("Source M60 support-held donor box",transform);
   var raw=Node("Source untransformed M60 mesh decode",Model);yield return visuals.Load("m60-main",raw);foreach(var renderer in raw.GetComponentsInChildren<MeshRenderer>()){Transform target=renderer.name.StartsWith("Cover/",StringComparison.Ordinal)?cover:renderer.name.StartsWith("Bolt/",StringComparison.Ordinal)?handle:art;renderer.transform.SetParent(target,false);}Destroy(raw.gameObject);
   raw=Node("Source M60 reload donor decode",Model);yield return visuals.Load("m60-donor",raw);foreach(var renderer in raw.GetComponentsInChildren<MeshRenderer>()){bool magazine=renderer.name.StartsWith("Magazine/",StringComparison.Ordinal);renderer.transform.SetParent(magazine?box:belt,false);if(magazine){boxes.Add(renderer);foreach(var parent in new[]{offered,held}){var copy=Node("Original M60 donor magazine",parent);copy.gameObject.AddComponent<MeshFilter>().sharedMesh=renderer.GetComponent<MeshFilter>().sharedMesh;copy.gameObject.AddComponent<MeshRenderer>().sharedMaterials=renderer.sharedMaterials;}}}Destroy(raw.gameObject);if(boxes.Count==0||cover.childCount==0||handle.childCount==0||belt.childCount==0)throw new InvalidOperationException("Actual M60 articulated source partitions absent");
   Muzzle=Node("Actual M60 source muzzle",Model);Muzzle.localPosition=V(R24M60Definition.Muzzle);Flash=Node("Source M60 flash plane",Model);Flash.localPosition=new Vector3(0,.04f,.93f);arrow=Node("Source PhysicalReloadMotionChevron",Model);yield return visuals.Load("m60-arrow",arrow);foreach(var renderer in arrow.GetComponentsInChildren<Renderer>()){renderer.sharedMaterial.SetColor("_EmissionColor",new Color(229f/255,182f/255,70f/255)*.55f);renderer.sharedMaterial.EnableKeyword("_EMISSION");}visuals.ReleaseLoadedBytes();PresentDock();
  }
  public void Present(R24M60Owner owner,Transform support,bool leftHanded,bool visible){if(!Ready||owner==null)return;var stage=owner.Stage;float sign=leftHanded?-1:1,progress=owner.MotionProgress;bool contact=owner.Contact&&owner.MotionStage==stage;
   float angle=stage==R24M60Stage.Ready||stage==R24M60Stage.NeedsCharge?0:1.35f;if(contact&&stage==R24M60Stage.BoxSeated)angle=1.35f*(1-progress);cover.localRotation=Quaternion.Euler(angle*Mathf.Rad2Deg,0,0);
   box.localPosition=V(R24M60Definition.Seat(leftHanded));if(contact&&stage==R24M60Stage.CoverOpen)box.localPosition-=Vector3.up*.09f*progress;offered.localPosition=V(R24M60Definition.Offer(leftHanded));
   bool seated=stage==R24M60Stage.Ready||stage==R24M60Stage.CoverOpen||stage==R24M60Stage.NeedsFeed||stage==R24M60Stage.BoxSeated||stage==R24M60Stage.NeedsCharge;box.gameObject.SetActive(seated);belt.gameObject.SetActive(seated&&owner.Loaded>0);belt.localScale=new Vector3(sign,1,1);float x=.0762f-(owner.BeltFed?0:.08f);if(contact&&stage==R24M60Stage.NeedsFeed)x=.0762f-.08f*(1-progress);belt.localPosition=new Vector3(x*sign,.0254f,-.01905f);
   handle.localPosition=V(R24M60Definition.Handle(leftHanded));if(contact&&stage==R24M60Stage.NeedsCharge)handle.localPosition-=Vector3.forward*.11f*progress;
   offered.gameObject.SetActive(visible&&stage==R24M60Stage.BoxRemoved&&owner.Reserve!=0);held.gameObject.SetActive(visible&&stage==R24M60Stage.HoldingBox&&support!=null);if(held.gameObject.activeSelf){held.SetPositionAndRotation(support.position,support.rotation*R23TrackedGripPose.LocalRotation);held.localScale=Vector3.one;}
   arrow.gameObject.SetActive(visible&&stage!=R24M60Stage.Ready&&stage!=R24M60Stage.BoxRemoved);var point=V(R24M60Definition.Grab(stage,leftHanded));if(stage==R24M60Stage.BoxSeated)point=cover.localPosition+cover.localRotation*V(R24M60Definition.CoverGrab);arrow.localPosition=point+Vector3.right*.06f;Vector3 direction=stage==R24M60Stage.CoverOpen||stage==R24M60Stage.BoxSeated?Vector3.down:stage==R24M60Stage.NeedsFeed?Vector3.right*sign:stage==R24M60Stage.NeedsCharge?Vector3.back:Vector3.up;arrow.localRotation=Quaternion.FromToRotation(Vector3.up,direction);
  }
  public void PresentDock(){if(cover!=null)cover.localRotation=Quaternion.identity;if(box!=null){box.localPosition=V(R24M60Definition.BoxHome);box.gameObject.SetActive(true);}if(belt!=null){belt.gameObject.SetActive(true);belt.localScale=Vector3.one;belt.localPosition=new Vector3(.0762f,.0254f,-.01905f);}if(handle!=null)handle.localPosition=V(R24M60Definition.HandleHome);ClearTransient();}
  public bool PartVisible(Transform item){return !(box!=null&&item.IsChildOf(box)&&!box.gameObject.activeSelf)&&!(belt!=null&&item.IsChildOf(belt)&&!belt.gameObject.activeSelf);}
  public bool IsTransient(Transform item){return arrow!=null&&(item==arrow||item.IsChildOf(arrow))||offered!=null&&(item==offered||item.IsChildOf(offered))||held!=null&&(item==held||item.IsChildOf(held));}
  public void ClearTransient(){if(offered!=null)offered.gameObject.SetActive(false);if(held!=null)held.gameObject.SetActive(false);if(arrow!=null)arrow.gameObject.SetActive(false);}
  static Transform Node(string name,Transform parent){var t=new GameObject(name).transform;t.gameObject.layer=18;t.SetParent(parent,false);return t;}static Vector3 V(Ashfall.Core.Float3 p){return new Vector3(p.X,p.Y,p.Z);}
  void OnDisable(){ClearTransient();}void OnDestroy(){ClearTransient();foreach(var part in new[]{art,cover,box,belt,handle,offered,held,arrow,Muzzle,Flash})if(part!=null)Destroy(part.gameObject);if(visuals!=null)visuals.Dispose();}
 }
}
